package org.light.challenge.core.agent.models

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import ai.koog.agents.core.tools.annotations.LLMDescription

/**
 * Rules wrapper model for LLM structured data generation.
 * Used to represent a collection of rules that should be generated by the LLM.
 */
@Serializable
@SerialName("LLMRules")
@LLMDescription("Collection of workflow rules for invoice processing")
data class LLMRules(
    @property:LLMDescription("List of workflow rules to be generated based on the user prompt")
    val rules: List<LLMRule>
) 